<script setup lang="ts">
import { Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { ArrowRight, CalendarDays, HeartPulse, Phone, ShieldCheck, UserRound, UsersRound } from '@lucide/vue';
type Team = { id: number; name: string; color: string };
type Person = { id: number; name: string; phone?: string | null; relationship?: string };
type Attendance = { id: number; status: string; title: string; date: string; note: string | null };
type Athlete = { id: number; membership_number: string; full_name: string; first_name: string; last_name: string; national_code: string | null; phone: string | null; birth_date: string | null; gender: string; position: string | null; jersey_number: number | null; is_active: boolean; emergency_name: string | null; emergency_phone: string | null; medical_notes: string | null; teams: Team[]; guardians: Person[]; coaches: Person[]; attendance_rate: number; attendance: Attendance[] };
defineProps<{ athlete: Athlete; canManage: boolean }>();
const statusLabel = (value: string) => ({ present: 'حاضر', late: 'تأخیر', absent: 'غایب', excused: 'موجه' }[value] || value);
const statusClass = (value: string) => ['present', 'late'].includes(value) ? 'tag-ok' : value === 'absent' ? 'tag-danger' : 'tag-warn';
const dateLabel = (value: string) => new Intl.DateTimeFormat('fa-IR', { day: 'numeric', month: 'short' }).format(new Date(`${value}T12:00:00`));
</script>

<template>
    <AppLayout :title="`پرونده ${athlete.full_name}`" eyebrow="پروفایل ورزشکار" active="manager">
        <Link href="/athletes" class="mb-4 inline-flex items-center gap-2 text-[10px] font-black text-[#657580]"><ArrowRight :size="15" /> بازگشت به فهرست ورزشکاران</Link>
        <section class="athlete-pass mb-5"><div class="athlete-avatar">{{ athlete.first_name.slice(0, 1) }}{{ athlete.last_name.slice(0, 1) }}</div><div class="relative z-10 flex-1"><p class="text-[9px] font-bold text-[#f29a66]">{{ athlete.membership_number }}</p><h2 class="mt-1 text-xl font-black text-white">{{ athlete.full_name }}</h2><div class="mt-3 flex flex-wrap gap-2"><span v-for="team in athlete.teams" :key="team.id" class="border border-white/20 px-2 py-1 text-[9px] font-bold text-[#d6e0e6]">{{ team.name }}</span><span class="border border-white/20 px-2 py-1 text-[9px] font-bold text-[#d6e0e6]">{{ athlete.position || 'پست تعیین نشده' }}</span></div></div><div class="athlete-status"><ShieldCheck :size="14" />{{ athlete.is_active ? 'عضویت فعال' : 'عضویت غیرفعال' }}</div><div v-if="athlete.jersey_number" class="athlete-number">{{ athlete.jersey_number }}</div></section>
        <div class="grid gap-5 xl:grid-cols-[1.3fr_.7fr]">
            <section class="panel-flat"><header class="panel-head"><div><h3>اطلاعات پایه و عضویت</h3><p>اطلاعات ثبت‌شده در پرونده باشگاه</p></div><UserRound :size="19" class="text-[#d4672c]" /></header><div class="grid sm:grid-cols-2"><div class="profile-field"><span>شماره تماس</span><strong dir="ltr">{{ athlete.phone || 'ثبت نشده' }}</strong></div><div class="profile-field"><span>کد ملی</span><strong dir="ltr">{{ athlete.national_code || 'ثبت نشده' }}</strong></div><div class="profile-field"><span>تاریخ تولد</span><strong>{{ athlete.birth_date || 'ثبت نشده' }}</strong></div><div class="profile-field"><span>جنسیت</span><strong>{{ athlete.gender === 'female' ? 'دختر' : 'پسر' }}</strong></div></div></section>
            <section class="panel-flat"><header class="panel-head"><div><h3>کادر فنی</h3><p>مربیان دارای دسترسی به این ورزشکار</p></div><UsersRound :size="19" class="text-[#d4672c]" /></header><div class="p-5"><div v-for="coach in athlete.coaches" :key="coach.id" class="person-row"><div class="user-initial">{{ coach.name.slice(0, 1) }}</div><strong>{{ coach.name }}</strong><span class="tag-ok">مربی</span></div><p v-if="!athlete.coaches.length" class="text-[10px] text-[#8a959b]">برای تیم این ورزشکار مربی تعیین نشده است.</p></div></section>
            <section class="panel-flat"><header class="panel-head"><div><h3>سرپرست و تماس اضطراری</h3><p>اطلاعات لازم برای ارتباط سریع</p></div><Phone :size="19" class="text-[#d4672c]" /></header><div class="grid sm:grid-cols-2"><div class="profile-field"><span>سرپرست متصل</span><strong>{{ athlete.guardians[0]?.name || 'ثبت نشده' }}</strong><small>{{ athlete.guardians[0]?.relationship }}</small></div><div class="profile-field"><span>شماره سرپرست</span><strong dir="ltr">{{ athlete.guardians[0]?.phone || 'ثبت نشده' }}</strong></div><div class="profile-field"><span>تماس اضطراری</span><strong>{{ athlete.emergency_name || 'ثبت نشده' }}</strong></div><div class="profile-field"><span>شماره اضطراری</span><strong dir="ltr">{{ athlete.emergency_phone || 'ثبت نشده' }}</strong></div></div></section>
            <section class="panel-flat"><header class="panel-head"><div><h3>ملاحظات پزشکی</h3><p>اطلاعات قابل مشاهده برای کادر مجاز</p></div><HeartPulse :size="19" class="text-[#d4672c]" /></header><p class="p-5 text-[11px] leading-7 text-[#53636e]">{{ athlete.medical_notes || 'مورد پزشکی خاصی در پرونده ثبت نشده است.' }}</p></section>
            <section class="panel-flat xl:col-span-2"><header class="panel-head"><div><h3>سابقه حضور در تمرین</h3><p>آخرین رکوردهای ثبت‌شده برای ورزشکار</p></div><div class="text-left"><strong class="block text-xl font-black text-[#1f7795]">{{ athlete.attendance_rate }}٪</strong><span class="text-[8px] text-[#849098]">نرخ حضور</span></div></header><div class="overflow-x-auto"><table class="sport-table"><thead><tr><th>تاریخ</th><th>جلسه</th><th>وضعیت</th><th>یادداشت</th></tr></thead><tbody><tr v-for="record in athlete.attendance" :key="record.id"><td>{{ dateLabel(record.date) }}</td><td><strong>{{ record.title }}</strong></td><td><span :class="statusClass(record.status)">{{ statusLabel(record.status) }}</span></td><td>{{ record.note || '—' }}</td></tr><tr v-if="!athlete.attendance.length"><td colspan="4" class="py-8 text-center text-[#8a959b]">هنوز سابقه حضوری ثبت نشده است.</td></tr></tbody></table></div></section>
        </div>
    </AppLayout>
</template>
